import test from 'node:test';
import assert from 'node:assert/strict';
import { Machine } from '../machine/machine.mjs';
import { Bus } from '../bus/bus.mjs';
import { Cpu } from '../cpu/cpu.mjs';

// Independent fixed vectors, not generated by the executor's ModR/M logic.
// Registers: BX=0100 BP=0300 SI=0020 DI=0040. Segment bases are distinct.
const baseForms = [
  { rm: 0, offset: 0x0120, segment: 0x1000, name: 'BX+SI' },
  { rm: 1, offset: 0x0140, segment: 0x1000, name: 'BX+DI' },
  { rm: 2, offset: 0x0320, segment: 0x2000, name: 'BP+SI' },
  { rm: 3, offset: 0x0340, segment: 0x2000, name: 'BP+DI' },
  { rm: 4, offset: 0x0020, segment: 0x1000, name: 'SI' },
  { rm: 5, offset: 0x0040, segment: 0x1000, name: 'DI' },
  { rm: 6, offset: 0x0300, segment: 0x2000, name: 'BP' },
  { rm: 7, offset: 0x0100, segment: 0x1000, name: 'BX' },
];
const regs = {ax:0xa1b2,bx:0x100,bp:0x300,si:0x20,di:0x40,ds:0x1000,ss:0x2000,flags:0x8d7};
const physical = (segment, offset) => segment * 16 + offset;

function one(program, registers=regs) {
  return new Machine({ profile:'diagnostic-compute-v1', program:Uint8Array.from(program), registers });
}

test('MOV word stores decode all 16-bit memory forms, displacement signs and default segments', () => {
  for (const form of baseForms) {
    for (const mode of [0,1,2]) {
      // mod=00,r/m=110 is direct, rather than BP.
      const direct = mode===0 && form.rm===6;
      const disp = direct ? [0x34,0x12] : mode===1 ? [0xf0] : mode===2 ? [0x21,0x00] : [];
      const offset = direct ? 0x1234 : (form.offset + (mode===1 ? -16 : mode===2 ? 33 : 0)) & 0xffff;
      const segment = direct ? 0x1000 : form.segment;
      const encoded = [0x89,(mode<<6)|form.rm,...disp]; // MOV [r/m16],AX
      const m=one(encoded);
      const address=physical(segment,offset);
      const other=physical(segment===0x1000?0x2000:0x1000,offset);
      m.bus.write8(other,0x77);m.bus.write8(other+1,0x88);
      assert.equal(m.step().status,'retired',`${form.name} mod ${mode}`);
      assert.equal(m.bus.read8(address),0xb2,`${form.name} low byte mod ${mode}`);
      assert.equal(m.bus.read8(address+1),0xa1,`${form.name} high byte mod ${mode}`);
      assert.equal(m.bus.read8(other),0x77,`${form.name} alternate segment mod ${mode}`);
      assert.equal(m.bus.read8(other+1),0x88);
      assert.equal(m.cpu.registers.flags,0x8d7);
      assert.equal(m.cpu.registers.ip,0x7c00+encoded.length);
    }
  }
});

test('word reads are little-endian and byte register forms preserve the other alias', () => {
  // MOV AX,[BP-2] uses SS and reads two bytes in little-endian order.
  let m=one([0x8b,0x46,0xfe]);m.bus.write8(physical(0x2000,0x2fe),0x34);m.bus.write8(physical(0x2000,0x2ff),0x12);
  assert.equal(m.step().status,'retired');assert.equal(m.cpu.registers.ax,0x1234);assert.equal(m.cpu.registers.flags,0x8d7);
  // MOV AH,[BX+SI] updates AH but not AL; MOV [BX+SI],AL takes AL, not AH.
  m=one([0x8a,0x20,0x88,0x00]);m.bus.write8(physical(0x1000,0x120),0x5a);
  assert.equal(m.step().status,'retired');assert.equal(m.cpu.registers.ax,0x5ab2);
  assert.equal(m.step().status,'retired');assert.equal(m.bus.read8(physical(0x1000,0x120)),0xb2);
});

test('effective offsets wrap at 16 bits before segment translation', () => {
  // BX+SI+disp8 = FFF0+0020-30 = FFF2; BX+DI+disp16 = FFF0+0040+30 = 0060.
  const r={...regs,bx:0xfff0,si:0x20,di:0x40};
  let m=one([0x89,0x40,0xe2],r);assert.equal(m.step().status,'retired');
  assert.equal(m.bus.read8(physical(0x1000,0xfff2)),0xb2);
  m=one([0x89,0x81,0x30,0x00],r);assert.equal(m.step().status,'retired');
  assert.equal(m.bus.read8(physical(0x1000,0x0060)),0xb2);
});

test('word writes reject segment crossing and unmapped second byte before changing RAM or registers', () => {
  let m=one([0x89,0x07],{...regs,bx:0xffff});
  const address=physical(0x1000,0xffff);m.bus.write8(address,0x55);m.bus.write8(physical(0x1000,0),0x66);
  const before={...m.cpu.registers};const result=m.step();
  assert.equal(result.status,'unsupported-platform-access');assert.equal(result.retired,false);assert.deepEqual(m.cpu.registers,before);
  assert.equal(m.bus.read8(address),0x55);assert.equal(m.bus.read8(physical(0x1000,0)),0x66);

  // A small bus makes FFFF mapped but 10000 unmapped; no partial low-byte write.
  const bus=new Bus({size:0x10000});bus.write8(0x7c00,0x89);bus.write8(0x7c01,0x07);bus.write8(0xffff,0x44);
  const cpu=new Cpu(bus,{profile:'diagnostic-compute-v1',registers:{...regs,ds:0x0800,bx:0x7fff}});
  const prior={...cpu.registers};const stop=cpu.step();assert.equal(stop.status,'unsupported-platform-access');assert.equal(stop.retired,false);
  assert.deepEqual(cpu.registers,prior);assert.equal(bus.read8(0xffff),0x44);
});

test('register-direct ModR/M maps all byte aliases and 16-bit registers', () => {
  const byteRegisters=['ax','cx','dx','bx'];
  const init={ax:0x1020,cx:0x3040,dx:0x5060,bx:0x7080,sp:0x1111,bp:0x2222,si:0x3333,di:0x4444,flags:0x8d7};
  const byteValues=[0x20,0x40,0x60,0x80,0x10,0x30,0x50,0x70];
  for(let src=0;src<8;src++) for(let dst=0;dst<8;dst++) {
    const m=one([0x88,0xc0|(src<<3)|dst],init); // MOV r/m8,r8
    const expected={...init};const dest=byteRegisters[dst%4];
    expected[dest] = dst<4 ? (init[dest]&0xff00)|byteValues[src] : (init[dest]&0x00ff)|(byteValues[src]<<8);
    assert.equal(m.step().status,'retired',`byte src ${src} dst ${dst}`);
    for(const key of Object.keys(init)) assert.equal(m.cpu.registers[key],expected[key],`byte src ${src} dst ${dst} ${key}`);
  }
  const words=['ax','cx','dx','bx','sp','bp','si','di'];
  for(let src=0;src<8;src++) for(let dst=0;dst<8;dst++) {
    const m=one([0x89,0xc0|(src<<3)|dst],init); // MOV r/m16,r16
    const expected={...init,[words[dst]]:init[words[src]]};
    assert.equal(m.step().status,'retired',`word src ${src} dst ${dst}`);
    for(const key of Object.keys(init)) assert.equal(m.cpu.registers[key],expected[key],`word src ${src} dst ${dst} ${key}`);
  }
});

test('both displacement widths sign-extend correctly, and invalid word reads have no effects', () => {
  let m=one([0x89,0x47,0x7f]); // MOV [BX+127],AX
  assert.equal(m.step().status,'retired');assert.equal(m.bus.read8(physical(0x1000,0x017f)),0xb2);
  m=one([0x89,0x87,0x00,0xff]); // MOV [BX-256],AX
  assert.equal(m.step().status,'retired');assert.equal(m.bus.read8(physical(0x1000,0x0000)),0xb2);
  m=one([0x8b,0x07],{...regs,bx:0xffff}); // MOV AX,[BX] crosses segment limit
  const before={...m.cpu.registers};const outcome=m.step();assert.equal(outcome.status,'unsupported-platform-access');
  assert.equal(outcome.retired,false);assert.deepEqual(m.cpu.registers,before);
  const bus=new Bus({size:0x10000});bus.write8(0x7c00,0x8b);bus.write8(0x7c01,0x07);bus.write8(0xffff,0x12);
  const cpu=new Cpu(bus,{profile:'diagnostic-compute-v1',registers:{...regs,ds:0x0800,bx:0x7fff}});
  const prior={...cpu.registers};const stopped=cpu.step();assert.equal(stopped.status,'unsupported-platform-access');
  assert.equal(stopped.retired,false);assert.deepEqual(cpu.registers,prior);
});

test('word data accesses apply the A20 gate separately to each physical byte', () => {
  const bus=new Bus({a20:false});
  // MOV [BX],AX at 2000:7C00; DS:BX = FFFF:000F -> FFFFF and 100000.
  bus.write8(0x27c00,0x89);bus.write8(0x27c01,0x07);
  const cpu=new Cpu(bus,{profile:'diagnostic-compute-v1',registers:{cs:0x2000,ds:0xffff,bx:0x000f,ax:0xa5c3}});
  assert.equal(cpu.step().status,'retired');
  assert.equal(bus.read8(0xfffff),0xc3);assert.equal(bus.read8(0),0xa5);
});
